var script = {
  props: {
    show: {
      type: Boolean,
      default: false
    },
    option: {
      type: Object,
      'default': () => ({
        top_height: '0',
        tab_height: '75px'
      })
    },
    routes: {
      type: Array,
      'default': () => [{
        name: 'home',
        path: '/',
        icon: 'fas fa-home'
      }]
    }
  },

  mounted() {
    this.sidebar_show = this.show;
  },

  data() {
    return {
      sidebar_show: false
    };
  },

  methods: {
    onBack() {
      this.$router.go(-1);
    },

    onChangePath(name) {
      this.$router.push({
        name: name
      });
    },

    onSidebarClick() {
      if (this.sidebar_show == false) {
        this.sidebar_show = true;
        this.$emit('input', true);
      } else {
        this.sidebar_show = false;
        this.$emit('input', false);
      }
    }

  }
};
